function bkLevenshtein(a, b){
  a=String(a); b=String(b);
  var m=a.length, n=b.length;
  if(m===0) return n;
  if(n===0) return m;
  var prev=new Array(n+1), cur=new Array(n+1), i, j;
  for(j=0;j<=n;j++) prev[j]=j;
  for(i=1;i<=m;i++){
    cur[0]=i;
    for(j=1;j<=n;j++){
      cur[j]=Math.min(prev[j]+1, cur[j-1]+1, prev[j-1]+(a[i-1]===b[j-1]?0:1));
    }
    var t=prev; prev=cur; cur=t;
  }
  return prev[n];
}
function bkCreate(){
  return { root:null, size:0 };
}
function bkAdd(tree, word){
  var w=String(word);
  if(!w) return tree;
  if(!tree.root){ tree.root={ word:w, children:{} }; tree.size=1; return tree; }
  var node=tree.root;
  for(;;){
    var d=bkLevenshtein(w, node.word);
    if(d===0) return tree;
    if(node.children[d]) node=node.children[d];
    else { node.children[d]={ word:w, children:{} }; tree.size++; return tree; }
  }
}
function bkBuild(words){
  var t=bkCreate();
  for(var i=0;i<words.length;i++) bkAdd(t, words[i]);
  return t;
}
function bkSearch(tree, word, maxDist){
  var w=String(word), md=Math.max(0, Math.floor(maxDist||0));
  var out=[];
  if(!tree||!tree.root) return out;
  var stack=[tree.root];
  while(stack.length){
    var node=stack.pop();
    var d=bkLevenshtein(w, node.word);
    if(d<=md) out.push({ word:node.word, dist:d });
    var lo=d-md, hi=d+md, k;
    for(k in node.children){
      var kd=Number(k);
      if(kd>=lo&&kd<=hi) stack.push(node.children[k]);
    }
  }
  out.sort(function(p,q){ return p.dist-q.dist || (p.word<q.word?-1:1); });
  return out;
}
function bkDepth(tree){
  if(!tree||!tree.root) return 0;
  var walk=function(node){
    var best=1, k;
    for(k in node.children){
      var d=1+walk(node.children[k]);
      if(d>best) best=d;
    }
    return best;
  };
  return walk(tree.root);
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { bkLevenshtein:bkLevenshtein, bkCreate:bkCreate, bkAdd:bkAdd,
    bkBuild:bkBuild, bkSearch:bkSearch, bkDepth:bkDepth };
}
if (typeof window !== 'undefined') {
  window.BktreeForgePure = { bkLevenshtein:bkLevenshtein, bkCreate:bkCreate, bkAdd:bkAdd,
    bkBuild:bkBuild, bkSearch:bkSearch, bkDepth:bkDepth };
}
